script:
const btn = document.getElementById('demoBtn');
  const cvName = document.getElementById('cvName');
  const cvLine = document.getElementById('cvLine');
  const cvSkills = document.getElementById('cvSkills');
  const cvPlaceholder = document.getElementById('cvPlaceholder');
  const cvStampWrap = document.getElementById('cvStampWrap');
  const cvId = document.getElementById('cvId');

  btn.addEventListener('click', () => {
    const name = document.getElementById('demoName').value.trim() || 'Your name';
    const skill = document.getElementById('demoSkill').value || 'Data Entry';
    const years = document.getElementById('demoYears').value;
    const town = document.getElementById('demoTown').value.trim();

    cvPlaceholder.style.display = 'none';
    cvStampWrap.classList.remove('show');
    cvSkills.innerHTML = '';

    cvName.textContent = name;
    const yearsPart = years ? `${years} yr${years == 1 ? '' : 's'} experience` : 'New to the workforce';
    const townPart = town ? ` · ${town}` : '';
    cvLine.textContent = `${skill}${townPart} · ${yearsPart}`;

    cvId.textContent = '#' + String(Math.floor(Math.random() * 900000) + 100000);

    const pills = skillSets[skill] || skillSets["Data Entry"];
    pills.forEach((p, i) => {
      const el = document.createElement('span');
      el.className = 'cv-skill-pill';
      el.textContent = p;
      cvSkills.appendChild(el);
      setTimeout(() => el.classList.add('show'), 150 + i * 120);
    });

    setTimeout(() => { cvStampWrap.classList.add('show'); }, 150 + pills.length * 120 + 250);
  });
